-- Replaces the Cases and Status tables from V1 with cases and case_log --
-- Ids are generated by the database and status is stored as the name of the CaseStatus enum --
ALTER TABLE Cases RENAME TO old_cases;
ALTER INDEX cases_pkey RENAME TO old_cases_pkey;

CREATE TABLE cases(
    id                           BIGINT        GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    organizer_id                 VARCHAR(30)   NOT NULL REFERENCES Organizer(OrganizerID),
    transaction_id               INT           NOT NULL REFERENCES Transaction(TransactionID),
    status                       VARCHAR(30)   NOT NULL,
    event_id                     VARCHAR(30)   NOT NULL,
    rejected_registration_number VARCHAR(30)   NOT NULL,
    rejected_account_number      VARCHAR(30)   NOT NULL,
    amount                       DECIMAL(10,2) NOT NULL,
    created_at                   TIMESTAMP     NOT NULL DEFAULT now(),
    CONSTRAINT cases_status_check CHECK (status IN (
        'REGISTERED', 'ORGANIZER_IDENTIFIED', 'BANK_DETAILS_REQUESTED', 'BANK_DETAILS_RECEIVED', 'RETRANSFERRED'))
);

CREATE TABLE case_log(
    id           BIGINT       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    case_id      BIGINT       NOT NULL REFERENCES cases(id),
    status       VARCHAR(30)  NOT NULL,
    performed_by VARCHAR(100) NULL, -- Should maybe be changed to a foreign key to a user
    created_at   TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT case_log_status_check CHECK (status IN (
        'REGISTERED', 'ORGANIZER_IDENTIFIED', 'BANK_DETAILS_REQUESTED', 'BANK_DETAILS_RECEIVED', 'RETRANSFERRED'))
);


-- Copy existing rows --
INSERT INTO cases(id, organizer_id, transaction_id, status, event_id,
                  rejected_registration_number, rejected_account_number, amount, created_at)
OVERRIDING SYSTEM VALUE
SELECT CaseID, OrganizerID, TransactionID,
       CASE Status WHEN 1 THEN 'REGISTERED'
                   WHEN 2 THEN 'ORGANIZER_IDENTIFIED'
                   WHEN 3 THEN 'BANK_DETAILS_REQUESTED' -- Should we have a step 4?
                   WHEN 5 THEN 'BANK_DETAILS_RECEIVED'
                   WHEN 6 THEN 'RETRANSFERRED' END,
       EventID, RejectedRegistrationNumber, RejectedAccountNumber, Amount, CreatedAt
FROM old_cases;

INSERT INTO case_log(id, case_id, status, performed_by, created_at)
OVERRIDING SYSTEM VALUE
SELECT s.StatusID, s.CaseID,
       CASE s.State WHEN 1 THEN 'REGISTERED'
                    WHEN 2 THEN 'ORGANIZER_IDENTIFIED'
                    WHEN 3 THEN 'BANK_DETAILS_REQUESTED'
                    WHEN 5 THEN 'BANK_DETAILS_RECEIVED'
                    WHEN 6 THEN 'RETRANSFERRED' END,
       u.Name, s.CreatedAt
FROM Status s
LEFT JOIN User_Table u ON u.UserID = s.UserID;

-- Continue the generated ids after copying rows --
SELECT setval(pg_get_serial_sequence('cases', 'id'), COALESCE(MAX(id), 0) + 1, false) FROM cases;
SELECT setval(pg_get_serial_sequence('case_log', 'id'), COALESCE(MAX(id), 0) + 1, false) FROM case_log;

DROP TABLE Status, old_cases CASCADE;

ALTER TABLE Retransfer
    ALTER COLUMN CaseID TYPE BIGINT,
    ADD CONSTRAINT retransfer_caseid_fkey FOREIGN KEY (CaseID) REFERENCES cases(id);

ALTER TABLE Note
    ALTER COLUMN CaseID TYPE BIGINT,
    ADD CONSTRAINT note_caseid_fkey FOREIGN KEY (CaseID) REFERENCES cases(id);
